-- FRESH PROJECT ONLY. Generated by build-setup.mjs; no users or sample data.
-- Destination: nkrxygqtptvarntzxawk (https://nkrxygqtptvarntzxawk.supabase.co).
-- Products remain empty. Import real hairstyle rows separately after setup.
-- Run the ENTIRE file in the new project's SQL Editor as postgres.
begin;
do $fresh_guard$
begin
  if to_regclass('public.products') is not null
      or to_regclass('public.hairstyles') is not null
      or to_regclass('public.profiles') is not null
      or to_regclass('public."Scan-profiles"') is not null
      or to_regclass('public.cart_items') is not null
      or to_regclass('public.saved_products') is not null
      or to_regclass('public.routine_schedules') is not null
      or to_regclass('public.routine_task_completions') is not null
      or to_regclass('private.api_requests') is not null
      or exists(select 1 from auth.users)
      or exists(select 1 from storage.buckets where id = 'profile-images') then
    raise exception 'Fresh setup requires no existing app tables, Auth users or profile-images bucket. No setup changes applied.';
  end if;
end
$fresh_guard$;

-- Empty compatibility table: the existing app/cart FKs still require it.
-- No old product records or fabricated product recommendations are inserted.
create table public.products (
  "No" integer primary key,
  product_id text unique not null,
  product_name text not null,
  price_lkr numeric,
  image_url text,
  description text,
  brand_name text,
  category text,
  target_skin_type text,
  target_concerns text,
  texture text,
  rating text
);

-- Only app-facing catalog fields are carried into the fresh project.
-- New IDs are generated; Android does not use legacy hairstyle IDs.
create table public.hairstyles (
  id bigint generated always as identity primary key,
  hairstyle_name text not null,
  face_shape text,
  gender text,
  hair_length text,
  image_url text
);


-- Source: 20260909000000_create_profiles.sql
-- SHA-256: 0e606f04e79e74e7280ae89e5d02135a46a245d00fecbf65cb260afd1df5ff3a
-- Stores the answers collected during onboarding for each authenticated user.
create table if not exists public.profiles (
    id uuid primary key references auth.users (id) on delete cascade,
    full_name text,
    age_range text,
    skin_type text,
    gender text,
    is_skin_sensitive boolean,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

alter table public.profiles enable row level security;

drop policy if exists "Users can read their own profile" on public.profiles;
create policy "Users can read their own profile"
on public.profiles
for select
to authenticated
using ((select auth.uid()) = id);

drop policy if exists "Users can insert their own profile" on public.profiles;
create policy "Users can insert their own profile"
on public.profiles
for insert
to authenticated
with check ((select auth.uid()) = id);

drop policy if exists "Users can update their own profile" on public.profiles;
create policy "Users can update their own profile"
on public.profiles
for update
to authenticated
using ((select auth.uid()) = id)
with check ((select auth.uid()) = id);

create or replace function public.set_profiles_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
    new.updated_at = now();
    return new;
end;
$$;

drop trigger if exists profiles_set_updated_at on public.profiles;
create trigger profiles_set_updated_at
before update on public.profiles
for each row execute function public.set_profiles_updated_at();


-- Source: 20260910000000_add_onboarding_completed.sql
-- SHA-256: fca4ad481f85da283c458f209a109a0d06424135a5eea2157c8464194340b852
-- Phase 5: explicit onboarding completion flag for public.profiles.
--
-- The initial schema (20260909000000_create_profiles.sql) treated "a profiles
-- row exists" as proof that onboarding finished. That is unsafe: any future
-- partial write (for example, storing a display name at signup, or a seed row
-- created by a trigger) would incorrectly look complete and skip the
-- questionnaire with missing data.
--
-- This migration adds an explicit, NOT NULL flag. The Android app sets it to
-- true only as part of the successful final onboarding profile upsert.

alter table public.profiles
    add column if not exists onboarding_completed boolean not null default false;

-- Backfill decision (deliberately NOT "mark every existing row completed"):
--
-- Only rows that already contain every REQUIRED onboarding answer are treated as
-- historically complete. In the shipped app the only writer of these columns is
-- the final onboarding save, which writes them together, so their combined
-- presence is reliable evidence that the questionnaire was finished.
--
-- skin_type is intentionally excluded from the condition because the onboarding
-- flow lets the user tap "Skip for now", leaving it legitimately null.
--
-- Any row missing a required answer keeps the safe default (false) and its owner
-- is asked the onboarding questions again rather than being silently advanced
-- past onboarding with incomplete data.

update public.profiles
set onboarding_completed = true
where onboarding_completed = false
  and age_range is not null
  and gender is not null
  and is_skin_sensitive is not null;

-- Row Level Security is unchanged. Adding a column does not alter existing
-- policies; the per-user SELECT/INSERT/UPDATE policies from the initial
-- migration continue to restrict every row to auth.uid() = id. No new policy is
-- required because onboarding_completed lives on the same row the user already
-- owns. The one-time UPDATE above runs with migration privileges, never from the
-- client and never with a service-role key embedded in the app.


