    add column if not exists profile_image_url text;


-- Source: 20260911000000_allow_authenticated_product_reads.sql
-- SHA-256: e94f54bfca4ef4a3598d18bc59ccac0ae47837362b7a37d9f269b4a175220230
-- The Discover catalog is available to signed-in app users.
alter table public.products enable row level security;

grant select on table public.products to authenticated;

do $$
begin
    if not exists (
        select 1
        from pg_policies
        where schemaname = 'public'
          and tablename = 'products'
          and policyname = 'Authenticated users can view products'
    ) then
