-- Source: 20261031000000_user_data_security.sql
-- SHA-256: 5cbbd05f825c9620206127250d2682a4d4be8d97fdcc0177230bfb413a568c5b
-- Capture the app-owned tables and enforce ownership even if older permissive policies exist.
-- Existing table shapes are preserved. Apply in staging first and inspect legacy constraints.
create table if not exists public.saved_products (
    profile_id uuid not null references public.profiles(id) on delete cascade,
    product_no integer not null references public.products("No") on delete cascade,
    created_at timestamptz not null default now(),
    primary key (profile_id, product_no)
);
create table if not exists public.cart_items (
    profile_id uuid not null references public.profiles(id) on delete cascade,
    product_no integer not null references public.products("No") on delete cascade,
    quantity integer not null default 1 check (quantity between 1 and 999),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    primary key (profile_id, product_no)
);
create table if not exists public."Scan-profiles" (
    id uuid primary key default gen_random_uuid(),
    user_prof_id uuid not null references public.profiles(id) on delete cascade,
    "Date_time" timestamptz not null default now(),
    dark_spots integer not null default 0,
    open_pores integer not null default 0,
    black_heads integer not null default 0,
    acne_scars integer not null default 0,
    papules integer not null default 0,
    whiteheads integer not null default 0,
    nodules integer not null default 0,
    cysts integer not null default 0,
    pustules integer not null default 0,
    freckles integer not null default 0
);

do $$
declare item record;
begin
    for item in select * from (values
        ('saved_products', 'profile_id'), ('cart_items', 'profile_id'), ('Scan-profiles', 'user_prof_id')
    ) as owned(table_name, owner_column)
    loop
        execute format('alter table public.%I enable row level security', item.table_name);
        execute format('revoke all on public.%I from anon, authenticated', item.table_name);
        execute format('grant select, insert, update, delete on public.%I to authenticated', item.table_name);
        execute format('drop policy if exists account_owner_guard on public.%I', item.table_name);
        execute format('create policy account_owner_guard on public.%I as restrictive for all to public using ((select auth.uid()) = %I) with check ((select auth.uid()) = %I)', item.table_name, item.owner_column, item.owner_column);
        execute format('drop policy if exists account_owner_access on public.%I', item.table_name);
        execute format('create policy account_owner_access on public.%I for all to authenticated using ((select auth.uid()) = %I) with check ((select auth.uid()) = %I)', item.table_name, item.owner_column, item.owner_column);
    end loop;
end $$;
-- NOT VALID avoids destroying or silently rewriting legacy data. New writes are checked.
alter table public.cart_items drop constraint if exists cart_quantity_bounds;
alter table public.cart_items add constraint cart_quantity_bounds check (quantity between 1 and 999) not valid;
alter table public.profiles drop constraint if exists profiles_allowed_age_range;
alter table public.profiles add constraint profiles_allowed_age_range
    check (age_range is null or age_range in ('14–24', '25–35', '36–45', '46–59', '60+')) not valid;
alter table public.profiles drop constraint if exists profiles_allowed_gender;
alter table public.profiles add constraint profiles_allowed_gender
    check (gender is null or gender in ('Female', 'Male', 'Other/Prefer not to say')) not valid;
-- Prevent pre-existing broad policies from defeating profile ownership.
drop policy if exists profiles_owner_guard on public.profiles;
create policy profiles_owner_guard on public.profiles as restrictive for all to public
    using ((select auth.uid()) = id) with check ((select auth.uid()) = id);
revoke all on public.profiles from anon;
revoke truncate, references, trigger on public.profiles from authenticated;
revoke all on public.hairstyles from anon;
revoke insert, update, delete, truncate, references, trigger on public.hairstyles from authenticated;

-- These restrictive policies combine with the existing own-folder policies.
drop policy if exists "profile-images bounded paths" on storage.objects;
create policy "profile-images bounded paths" on storage.objects as restrictive for all to public
using (bucket_id <> 'profile-images' or (storage.foldername(name))[1] = (select auth.uid()::text))
with check (bucket_id <> 'profile-images' or (
    (storage.foldername(name))[1] = (select auth.uid()::text)
    and name ~ '^[^/]+/[^/]+\.(jpg|jpeg|png|webp)$'
    and octet_length(name) <= 256
));


-- Source: 20261031010000_api_quotas.sql
-- SHA-256: 847c0edddad633149b1006c2186d5eea53c43e296ac1bd2d2a008778b7b085c8
-- Quotas live in Postgres, shared by all Edge Function instances. No client can reserve/release.
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
create table if not exists private.api_requests (
    id uuid primary key default gen_random_uuid(),
    user_id uuid not null references auth.users(id) on delete cascade,
    service text not null check (service in ('chat', 'weather', 'delete-account')),
    created_at timestamptz not null default now(),
    expires_at timestamptz not null,
    finished_at timestamptz
);
create index if not exists api_requests_user_service_time on private.api_requests(user_id, service, created_at);
alter table private.api_requests enable row level security;

create or replace function public.reserve_api_request(p_user_id uuid, p_service text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare minute_limit integer; day_limit integer; active_limit integer; reservation uuid;
begin
    if p_service = 'chat' then minute_limit := 10; day_limit := 100; active_limit := 2;
    elsif p_service = 'weather' then minute_limit := 30; day_limit := 500; active_limit := 4;
    elsif p_service = 'delete-account' then minute_limit := 2; day_limit := 10; active_limit := 1;
    else raise exception 'Invalid service'; end if;
    perform pg_advisory_xact_lock(hashtextextended(p_user_id::text || ':' || p_service, 0));
    delete from private.api_requests where user_id = p_user_id and service = p_service and created_at < now() - interval '2 days';
    if (select count(*) from private.api_requests where user_id = p_user_id and service = p_service and created_at >= now() - interval '1 minute') >= minute_limit
    or (select count(*) from private.api_requests where user_id = p_user_id and service = p_service and created_at >= date_trunc('day', now() at time zone 'UTC') at time zone 'UTC') >= day_limit
    or (select count(*) from private.api_requests where user_id = p_user_id and service = p_service and finished_at is null and expires_at > now()) >= active_limit then
        return null;
    end if;
    insert into private.api_requests(user_id, service, expires_at)
        values (p_user_id, p_service, now() + interval '90 seconds') returning id into reservation;
    return reservation;
end $$;
create or replace function public.release_api_request(p_request_id uuid)
returns void language sql security definer set search_path = '' as $$
    update private.api_requests set finished_at = now() where id = p_request_id;
$$;
revoke all on function public.reserve_api_request(uuid, text) from public, anon, authenticated;
revoke all on function public.release_api_request(uuid) from public, anon, authenticated;
grant execute on function public.reserve_api_request(uuid, text) to service_role;
grant execute on function public.release_api_request(uuid) to service_role;


-- Source: 20261031020000_account_deletion.sql
-- SHA-256: 94df8fbfd137b70901fbcb1599660db549ee1d3d322696930319a5606d0e28e4
-- Called only by the verified delete-account Edge Function, after storage cleanup.
-- Database deletion is atomic; existing access tokens lose their backing profile/data.
create or replace function public.delete_account_data(p_user_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
begin
    if exists (select 1 from storage.objects where bucket_id = 'profile-images'
        and (storage.foldername(name))[1] = p_user_id::text) then
        raise exception 'Remove account photos before deleting account';
    end if;
    delete from public."Scan-profiles" where user_prof_id = p_user_id;
    delete from public.cart_items where profile_id = p_user_id;
    delete from public.saved_products where profile_id = p_user_id;
    delete from public.profiles where id = p_user_id;
    delete from auth.users where id = p_user_id;
end $$;
revoke all on function public.delete_account_data(uuid) from public, anon, authenticated;
grant execute on function public.delete_account_data(uuid) to service_role;


-- Source: 20261104000000_combined_progress.sql
-- SHA-256: 8efa5bbc0918052961762c98cb619aa9f28e036f463b4879d1048c86e49a8c9f
-- Apply after the existing user-data security migrations. No legacy counts/settings are invented.

alter table public."Scan-profiles" add column if not exists progress_scan_id uuid not null default gen_random_uuid();
alter table public."Scan-profiles" add column if not exists detection_settings text;
create unique index if not exists scan_progress_id_unique on public."Scan-profiles"(progress_scan_id);
create index if not exists scan_progress_owner_date on public."Scan-profiles"(user_prof_id, "Date_time");

create table if not exists public.routine_schedules (
    id uuid primary key default gen_random_uuid(),
    profile_id uuid not null references public.profiles(id) on delete cascade,
    effective_from timestamptz not null,
    zone_id text not null,
    plan jsonb not null check (jsonb_typeof(plan) = 'object'),
    created_at timestamptz not null default now(),
    unique(profile_id, effective_from)
);
create table if not exists public.routine_task_completions (
    schedule_id uuid not null references public.routine_schedules(id) on delete cascade,
    profile_id uuid not null references public.profiles(id) on delete cascade,
    task_date date not null,
    morning boolean not null,
    step_index integer not null check(step_index between 0 and 19),
    completed boolean not null,
    updated_at timestamptz not null default now(),
    primary key(schedule_id, task_date, morning, step_index)
);
create index if not exists routine_completion_owner on public.routine_task_completions(profile_id);

alter table public.routine_schedules enable row level security;
alter table public.routine_task_completions enable row level security;
revoke all on public.routine_schedules, public.routine_task_completions from public, anon, authenticated;
grant select on public.routine_schedules, public.routine_task_completions to authenticated;
drop policy if exists routine_schedule_owner on public.routine_schedules;
create policy routine_schedule_owner on public.routine_schedules for select to authenticated
    using (profile_id = (select auth.uid()));
drop policy if exists routine_completion_owner on public.routine_task_completions;
create policy routine_completion_owner on public.routine_task_completions for select to authenticated
    using (profile_id = (select auth.uid()));

-- Only this bounded RPC can write schedules. Caller identity and dates are server-derived.
-- Initial activation is now; later changes begin at the next midnight in the stored zone.
-- A not-yet-active schedule can be revised; an active/historical snapshot cannot be changed.
create or replace function public.register_routine_schedule(p_plan jsonb, p_zone text)
returns void language plpgsql security definer set search_path = '' as $$
declare
    owner_id uuid := auth.uid();
    active public.routine_schedules%rowtype;
    pending public.routine_schedules%rowtype;
    starts timestamptz;
    step jsonb;
begin
    if owner_id is null then raise exception 'Sign in to save your routine'; end if;
    perform 1 from public.profiles where id = owner_id for update;
    if not found then raise exception 'Profile is unavailable'; end if;
    if p_zone is null or not exists(select 1 from pg_timezone_names where name = p_zone) then
        raise exception 'Invalid time zone';
    end if;
    if p_plan is null or jsonb_typeof(p_plan) <> 'object'
        or jsonb_typeof(p_plan->'morning') is distinct from 'array'
        or jsonb_typeof(p_plan->'evening') is distinct from 'array'
        or octet_length(p_plan::text) > 131072 then raise exception 'Invalid routine'; end if;
    if jsonb_array_length(p_plan->'morning') > 20 or jsonb_array_length(p_plan->'evening') > 20 then
        raise exception 'Too many routine steps';
    end if;
    for step in select value from jsonb_array_elements((p_plan->'morning') || (p_plan->'evening')) loop
        if jsonb_typeof(step) <> 'object' or jsonb_typeof(step->'label') is distinct from 'string'
            or (step ? 'product' and step->'product' <> 'null'::jsonb and
                (jsonb_typeof(step->'product') <> 'object' or jsonb_typeof(step->'product'->'id') is distinct from 'string')) then
            raise exception 'Invalid routine step';
        end if;
    end loop;
    select * into active from public.routine_schedules
        where profile_id = owner_id and effective_from <= now() order by effective_from desc limit 1;
    select * into pending from public.routine_schedules
        where profile_id = owner_id and effective_from > now() order by effective_from limit 1;
    if active.id is null then
        insert into public.routine_schedules(profile_id, effective_from, zone_id, plan)
            values(owner_id, now(), p_zone, p_plan);
    elsif active.plan = p_plan and active.zone_id = p_zone then
        -- Cancelling a future revision never changes tasks that were already due.
        delete from public.routine_schedules where id = pending.id;
    else
        starts := ((now() at time zone active.zone_id)::date + 1)::timestamp at time zone active.zone_id;
        if pending.id is not null then
            update public.routine_schedules set plan = p_plan, zone_id = p_zone where id = pending.id;
        else
            insert into public.routine_schedules(profile_id, effective_from, zone_id, plan)
                values(owner_id, starts, p_zone, p_plan);
        end if;
    end if;
end $$;

-- Idempotent SET, never increment/toggle. One row per scheduled occurrence.
create or replace function public.set_routine_task_completion(
    p_schedule_id uuid, p_task_date date, p_morning boolean, p_step_index integer, p_completed boolean
) returns void language plpgsql security definer set search_path = '' as $$
declare
    owner_id uuid := auth.uid();
    schedule public.routine_schedules%rowtype;
    due_at timestamptz;
    step jsonb;
begin
    if owner_id is null then raise exception 'Sign in to save completion'; end if;
    select * into schedule from public.routine_schedules where id = p_schedule_id and profile_id = owner_id;
    if schedule.id is null or p_task_date is null or p_morning is null or p_completed is null
        or p_step_index is null or p_step_index not between 0 and 19 then raise exception 'Invalid scheduled task'; end if;
    step := schedule.plan -> (case when p_morning then 'morning' else 'evening' end) -> p_step_index;
    if step is null or step->'product' is null or step->'product' = 'null'::jsonb then
        raise exception 'This task has no scheduled product';
    end if;
    due_at := (p_task_date + (case when p_morning then time '08:00' else time '20:00' end)) at time zone schedule.zone_id;
    if due_at < schedule.effective_from or due_at > now() or exists(
        select 1 from public.routine_schedules where profile_id = owner_id
            and effective_from > schedule.effective_from and effective_from <= due_at
    ) then raise exception 'This task is not due in that schedule'; end if;
    insert into public.routine_task_completions(schedule_id, profile_id, task_date, morning, step_index, completed)
        values(p_schedule_id, owner_id, p_task_date, p_morning, p_step_index, p_completed)
    on conflict(schedule_id, task_date, morning, step_index)
        do update set completed = excluded.completed, updated_at = now();
end $$;
revoke all on function public.register_routine_schedule(jsonb,text) from public, anon;
revoke all on function public.set_routine_task_completion(uuid,date,boolean,integer,boolean) from public, anon;
grant execute on function public.register_routine_schedule(jsonb,text) to authenticated;
grant execute on function public.set_routine_task_completion(uuid,date,boolean,integer,boolean) to authenticated;
